--   docker exec -i naturdex-db-1 sh -c 'MYSQL_PWD="$MYSQL_ROOT_PASSWORD" mysql --default-character-set=utf8mb4 naturadex' < Database\salinas-arenales-san-pedro-pinatar-n2.sql
-- ================================================================================================

SET NAMES utf8mb4;

-- ------------------------------------------------------------------------------------------------
-- 1. El espacio. Sin esta fila, TODO lo demás carga cero filas en silencio.
-- ------------------------------------------------------------------------------------------------
INSERT INTO parks (slug, name, category, region, province, municipality, description, latitude, longitude, status)
VALUES ('salinas-arenales-san-pedro-pinatar', 'Salinas y Arenales de San Pedro del Pinatar', 'Parque Regional', 'Región de Murcia', 'Murcia', 'San Javier y San Pedro del Pinatar', 'Salinas en activo, dunas y pinares al norte del Mar Menor: charcas donde se concentran flamencos, cigüeñuelas y avocetas, y la playa de La Llana.', 37.81265, -0.76233, 'available')
ON DUPLICATE KEY UPDATE
    name = VALUES(name), category = VALUES(category), region = VALUES(region),
    province = VALUES(province), municipality = VALUES(municipality),
    description = VALUES(description), latitude = VALUES(latitude),
    longitude = VALUES(longitude), status = VALUES(status);

-- ------------------------------------------------------------------------------------------------
-- 2. Hábitats (15). `geometry` sale del geojson; sin ella el mapa dibuja un círculo.
-- ------------------------------------------------------------------------------------------------
