    SELECT 'dunas-moviles-embrionarias-2110', '2110', 'Dunas móviles embrionarias', 'Dunas', 'El primer relieve de arena de la playa, de apenas unos decímetros, que se forma donde una planta rastrera frena el viento y la arena se deposita a su alrededor. La construyen la grama de mar (Elymus farctus) y la juncia marina, capaces de crecer hacia arriba a medida que quedan enterradas. Es la duna naciente: si se pisa o se allana, todo el cordón dunar que hay detrás se queda sin recambio.', 0, 37.814172, -0.758009, '#6b8e23', '{"type":"MultiPolygon","coordinates":[[[[-0.763062,37.842566],[-0.762996,37.842459],[-0.762953,37.842388],[-0.762625,37.841855],[-0.762344,37.839106],[-0.762306,37.838609],[-0.762218,37.837463],[-0.76205,37.836437],[-0.761973,37.835963],[-0.761554,37.834862],[-0.761433,37.833472],[-0.761409,37.833393],[-0.76135,37.833337],[-0.761268,37.833311],[-0.761179,37.833314],[-0.76113,37.833335],[-0.7611,37.833348],[-0.761049,37.833406],[-0.761038,37.833471],[-0.761161,37.834918],[-0.761583,37.836027],[-0.761671,37.836563],[-0.761822,37.837492],[-0.761947,37.83913],[-0.762235,37.841938],[-0.762649,37.842612],[-0.762644,37.842636],[-0.763025,37.842712],[-0.763031,37.842713],[-0.763033,37.842701],[-0.763054,37.842604],[-0.763062,37.842566]]],[[[-0.762034,37.831388],[-0.761736,37.829968],[-0.76153,37.829153],[-0.761149,37.827733],[-0.760871,37.826453],[-0.760488,37.824803],[-0.760286,37.824103],[-0.760471,37.82321],[-0.760481,37.823163],[-0.760479,37.823138],[-0.760464,37.823117],[-0.759969,37.822847],[-0.75952,37.821238],[-0.759069,37.820279],[-0.758676,37.819093],[-0.758493,37.818328],[-0.758489,37.818288],[-0.758494,37.818261],[-0.758683,37.817127],[-0.758724,37.816479],[-0.758648,37.815808],[-0.758368,37.814852],[-0.758063,37.814132],[-0.757874,37.813448],[-0.757698,37.812749],[-0.757361,37.81192],[-0.756938,37.811108],[-0.756574,37.81026],[-0.756137,37.80947],[-0.755924,37.809043],[-0.75588,37.808621],[-0.755907,37.808168],[-0.756005,37.807627],[-0.756016,