    SELECT 'pastizales-salinos-mediterraneos-1410', '1410', 'Pastizales salinos mediterráneos (Juncetalia maritimi)', 'Salino', 'Praderas de juncos y gramíneas sobre suelos salinos que se encharcan en invierno y se resecan en verano, tierra adentro de las marismas y en el borde de saladares y ramblas salobres. La sal se concentra en la superficie al evaporarse el agua, de modo que solo prosperan plantas capaces de bombear agua contra ella. Forman un tapiz denso y verde que contrasta con los suelos desnudos de alrededor.', 0, 37.820121, -0.765292, '#b8860b', '{"type":"MultiPolygon","coordinates":[[[[-0.777537,37.834744],[-0.777529,37.83463],[-0.777512,37.8344],[-0.777405,37.833957],[-0.777168,37.833068],[-0.776991,37.832336],[-0.776869,37.83185],[-0.775868,37.829396],[-0.775777,37.829324],[-0.775649,37.828312],[-0.775324,37.826582],[-0.775118,37.825542],[-0.775141,37.824738],[-0.775098,37.824539],[-0.775074,37.824427],[-0.775079,37.824341],[-0.775106,37.824148],[-0.775171,37.823801],[-0.775215,37.823588],[-0.775296,37.823191],[-0.775422,37.822599],[-0.775506,37.822183],[-0.775558,37.82196],[-0.775584,37.821858],[-0.775693,37.821637],[-0.775846,37.821303],[-0.775911,37.821171],[-0.776061,37.820394],[-0.77599,37.820346],[-0.775511,37.820008],[-0.775105,37.819549],[-0.773139,37.816777],[-0.760658,37.799175],[-0.760557,37.798948],[-0.760467,37.798455],[-0.760425,37.79503],[-0.754334,37.792931],[-0.753744,37.795101],[-0.75351,37.795148],[-0.753388,37.795204],[-0.753287,37.795367],[-0.753308,37.795385],[-0.753316,37.795408],[-0.753311,37.795431],[-0.752913,37.796175],[-0.752712,37.79669],[-0.752495,37.797172],[-0.752872,37.79768],[-0.753748,37.799447],[-0.753896,37.799855],[-0.7539,37.799891],[-0.753912,37.800004],[-0.753839,37.80035],[-0.753679,37.800653],[-0.753535,37.800941],[-0.753353,37.801233],[-0.753315,37.801592],[-0.753471,37.802174],[-0.753713,37.802578],[-0.754145,37.803111],[-0.754607,37.803656],[-0.755054,37.804124],[-0.755595,37.804664],[-0.755832,37.805074],