    SELECT 'vegetacion-halonitrofila-anual-1310', '1310', 'Vegetación halonitrófila anual (Salicornia y otras)', 'Salino', 'Céspedes abiertos de plantas anuales y carnosas que colonizan el fango salino en cuanto el agua se retira, en los bordes de salinas, marismas y lagunas costeras. Dominan las salicornias y sosas anuales, tallos sin hojas visibles, articulados como pequeños cactus, que a final de verano se tiñen de rojo y anaranjado. Es una vegetación efímera: cada año se instala de nuevo sobre un suelo que ha vuelto a quedar desnudo.', 0, 37.821033, -0.766607, '#8fbc8f', '{"type":"Polygon","coordinates":[[[-0.777537,37.834744],[-0.777529,37.83463],[-0.777512,37.8344],[-0.777405,37.833957],[-0.777168,37.833068],[-0.776991,37.832336],[-0.776869,37.83185],[-0.775868,37.829396],[-0.775777,37.829324],[-0.775649,37.828312],[-0.775324,37.826582],[-0.775118,37.825542],[-0.775141,37.824738],[-0.775098,37.824539],[-0.775074,37.824427],[-0.775079,37.824341],[-0.775106,37.824148],[-0.775171,37.823801],[-0.775215,37.823588],[-0.775296,37.823191],[-0.775422,37.822599],[-0.775506,37.822183],[-0.775558,37.82196],[-0.775584,37.821858],[-0.775693,37.821637],[-0.775846,37.821303],[-0.775911,37.821171],[-0.776061,37.820394],[-0.77599,37.820346],[-0.775511,37.820008],[-0.775105,37.819549],[-0.773139,37.816777],[-0.760658,37.799175],[-0.760557,37.798948],[-0.760467,37.798455],[-0.760425,37.79503],[-0.754334,37.792931],[-0.753744,37.795101],[-0.754531,37.795292],[-0.754777,37.795531],[-0.754893,37.795736],[-0.754938,37.79616],[-0.75491,37.796585],[-0.754784,37.796997],[-0.754799,37.797433],[-0.754946,37.797971],[-0.755106,37.798427],[-0.75518,37.798909],[-0.75508,37.799218],[-0.754765,37.799482],[-0.754447,37.799679],[-0.754203,37.799796],[-0.754089,37.799897],[-0.754205,37.800034],[-0.754522,37.800275],[-0.755201,37.800454],[-0.755937,37.800545],[-0.756628,37.800473],[-0.757003,37.800529],[-0.757437,37.800767],[-0.757914,37.801214],[-0.758247,37.801614],[-0.758596,37.802254],[-0.7586