    SELECT 'dunas-litorales-con-2250', '2250', 'Dunas litorales con Juniperus spp.', 'Dunas', 'Sabinar o enebral crecido directamente sobre las dunas ya fijas, con las sabinas y enebros achaparrados y peinados por el viento marino, a veces tumbados sobre la arena y con las raíces al aire donde ésta se ha movido. Crecen muy despacio, así que un ejemplar de porte mediano puede tener siglos y una duna arrasada no lo recupera en una vida humana. Es el matorral leñoso más maduro que llega a formarse sobre arena litoral, y de los más raros: hoy sobrevive en manchas sueltas entre urbanizaciones y playas.', 1, 37.830721, -0.763398, '#cd853f', '{"type":"Polygon","coordinates":[[[-0.766412,37.832699],[-0.76641,37.832697],[-0.766163,37.832091],[-0.765715,37.828532],[-0.765438,37.8279],[-0.765206,37.827684],[-0.763455,37.826191],[-0.760471,37.82321],[-0.760286,37.824103],[-0.760488,37.824803],[-0.760871,37.826453],[-0.761149,37.827733],[-0.76153,37.829153],[-0.761736,37.829968],[-0.762034,37.831388],[-0.761827,37.831887],[-0.761151,37.832957],[-0.761139,37.83297],[-0.76108,37.833187],[-0.761105,37.833301],[-0.76113,37.833335],[-0.761179,37.833314],[-0.761268,37.833311],[-0.76135,37.833337],[-0.761409,37.833393],[-0.761433,37.833472],[-0.761554,37.834862],[-0.761973,37.835963],[-0.76205,37.836437],[-0.762098,37.836422],[-0.762243,37.836364],[-0.762373,37.836328],[-0.762503,37.836329],[-0.762778,37.836329],[-0.762887,37.836349],[-0.762908,37.836352],[-0.763026,37.836352],[-0.763168,37.836375],[-0.763298,37.836375],[-0.763457,37.836376],[-0.763616,37.836352],[-0.763876,37.836352],[-0.764064,37.836295],[-0.764208,37.836273],[-0.764382,37.836238],[-0.764555,37.836158],[-0.764657,37.836099],[-0.764758,37.83602],[-0.76486,37.835939],[-0.764961,37.835826],[-0.765062,37.835722],[-0.76512,37.83563],[-0.765178,37.83555],[-0.765207,37.835459],[-0.765265,37.835379],[-0.765338,37.835263],[-0.76541,37.835138],[-0.765483,37.835011],[-0.76557,37.834884],[-0.765584,37.834781],[-0.765643,37.83467