    SELECT 'Sabina negral', 'Juniperus phoenicea', 'flora', 'Conífera', 'Roquedos, arenales, acantilados y crestas ventosas sobre suelos pobres', 'Interés especial', 'Sabina de hojas diminutas en forma de escama, pegadas a la ramilla, que dan a las ramas un aspecto de cordón redondeado. Aguanta viento, sequía y salinidad como pocas plantas leñosas. Sus gálbulos —los falsos frutos— maduran de verde a un rojo pardusco en dos años.', NULL, 'Hojas en escama pegadas a la rama, no punzantes; Ramillas cilíndricas, como cordones; Gálbulos redondos que pasan de verde a pardo rojizo', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Juniperus_phoenicea1.jpg?width=1280', 'autor no indicado (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'GBIF: 15 ocurrencias dentro de los polígonos de hábitat del espacio (6 hábitats; barrido de 2026-08-17); EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Pinopsida', 'Pinales', 'Cupressaceae', 'Juniperus', 'LC', 'No catalogada en la Lista Roja de la Flora Vascular Española 2008', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', NULL, 5509, 2684640, NULL, NULL, NULL
    UNION ALL
    SELECT 'Pino carrasco', 'Pinus halepensis', 'flora', 'Conífera', 'Laderas secas y soleadas sobre calizas y margas, en clima mediterráneo cálido', 'LC', 'Pino de copa clara e irregular y follaje de un verde pálido, el más resistente a la sequía y a los suelos pobres de los pinos ibéricos. Sus piñas, alargadas y asimétricas, quedan colgadas años en la rama y liberan las semillas tras los incendios, lo que le permite recolonizar rápido.', NULL, 'Copa irregular y poco densa, de verde claro; Piñas asimétricas y persistentes, apuntando hacia atrás; Corteza clara y agrietada, rojiza en las ramas jóvenes', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pino_secolare_-_Castelleone_di_Suasa.JPG?width=1280', 'Accurimbono (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 15 ocurrencias dentro de los polígonos de hábitat del espacio (6 hábitats; barrido de 2026-08-17); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; Decreto n.º 259/2019, de 10 de octubre, PRUG del Parque Regional «Salinas y Arenales de San Pedro del Pinatar» (volumen III del Plan de gestión integral del Mar Menor), §2.3.1.2 y §2.3.3.2 (BORM n.º 242, de 19 de octubre de 2019): la norma la enumera en el Parque Regional «Salinas y Arenales de San Pedro del Pinatar», que es el propio espacio: a diferencia de los planes del Altiplano, aquí el inventario NO es el de la ZEC sino el del parque, porque el volumen III es su PRUG; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Pinopsida', 'Pinales', 'Pinaceae', 'Pinus', 'LC', 'No catalogada (especie forestal común)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 7118, 5285604, NULL, NULL, NULL
