    SELECT 'Barrilla pinchosa', 'Salsola kali', 'flora', 'Hierba', 'Arenas y gravas del primer cordón de playa y suelos removidos salinos', 'No catalogada', 'Hierba anual muy ramificada, de hojas carnosas rematadas en un pincho fino, que forma una bola. Al secarse se desprende del suelo y rueda con el viento dispersando las semillas. Coloniza la línea donde el mar deja restos de algas y madera.', NULL, 'Hojas carnosas terminadas en una punta pinchuda; Forma una mata redondeada que rueda al secarse; Tallos con finas líneas rojizas o rosadas', 'Verano y otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Salsola_kali_habito.jpg?width=1280', 'autor no indicado (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 7 ocurrencias dentro de los polígonos de hábitat del espacio (10 hábitats; barrido de 2026-08-17); Decreto n.º 259/2019, de 10 de octubre, PRUG del Parque Regional «Salinas y Arenales de San Pedro del Pinatar» (volumen III del Plan de gestión integral del Mar Menor), §2.3.1.2 y §2.3.3.2 (BORM n.º 242, de 19 de octubre de 2019): la norma la enumera en el Parque Regional «Salinas y Arenales de San Pedro del Pinatar», que es el propio espacio: a diferencia de los planes del Altiplano, aquí el inventario NO es el de la ZEC sino el del parque, porque el volumen III es su PRUG, que la cita como «Salsola kali subsp. kali»; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Amaranthaceae', 'Salsola', 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie común litoral)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 7912, 3083957, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cinomorio', 'Cynomorium coccineum', 'flora', 'Planta parásita', 'Saladares y matorrales halonitrófilos', 'Interés especial', 'Planta parásita sin clorofila, de aspecto de maza rojiza, que crece sobre las raíces de quenopodiáceas halófilas de los saladares y estepas salinas.', NULL, 'Inflorescencia carnosa rojo-oscura en maza; Sin hojas verdes (parásita); Aparece sobre raíces de plantas halófilas', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cynomorium_coccineum_vMH375.jpg?width=1280', 'autor no indicado (Public domain) · Wikimedia Commons', NULL, NULL, 5, NULL, 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'GBIF: 6 ocurrencias dentro de los polígonos de hábitat del espacio (8 hábitats; barrido de 2026-08-17); Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000175 (Salinas y Arenales de San Pedro del Pinatar), sección 3.3, que la cita como «Cynomorium coccineum L.»; Decreto n.º 259/2019, de 10 de octubre, PRUG del Parque Regional «Salinas y Arenales de San Pedro del Pinatar» (volumen III del Plan de gestión integral del Mar Menor), §2.3.1.2 y §2.3.3.2 (BORM n.º 242, de 19 de octubre de 2019): la norma la enumera en el Parque Regional «Salinas y Arenales de San Pedro del Pinatar», que es el propio espacio: a diferencia de los planes del Altiplano, aquí el inventario NO es el de la ZEC sino el del parque, porque el volumen III es su PRUG, con la categoría «De Interés Especial»; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Magnoliopsida', 'Saxifragales', 'Cynomoriaceae', 'Cynomorium', 'NE', 'No localizada en la Lista Roja de la Flora Vascular Española 2008 (pendiente de confirmar)', 'Especies de interés especial (De