    SELECT 'Esparraguera marítima', 'Asparagus macrorrhizus', 'flora', 'Hierba', NULL, 'Interés especial', 'Tallos de hasta 100 cm, herbácea, erecta. Tallos y ramas longitudinalmente estriado-papilosas. Cladodios de (5)10-30(50) x 0,3-0,8 mm, en fascículos de (3)4-7(11), erecto-patentes. Pedicelos de (4,5)6-10(12) mm. Nudos con (1)2(4) flores, de normal, no mezclados con los cladodios. Segmentos del periantio de 4-6 mm. Fruto en baya de (5)6-12(13) mm, rojo, con 2-6 semillas. Se incluye taxonómicamente en el subgénero Asparagus, está especialmente relacionado con A. officinalis L.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, NULL, 'https://commons.wikimedia.org/wiki/Special:FilePath/Asparagus_macrorrhizus60078.jpg?width=1280', 'Nanosanchez (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 5, NULL, 5, '{"categoria":"CEEA: En peligro de extinción (Orden TED/339/2023, de 30 de marzo)","ambito":"estatal","origen":"spainStatus del park.json"}', 1, 1, NULL, 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (7 hábitats; barrido de 2026-08-17); EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Tracheophyta', 'Liliopsida', 'Asparagales', 'Asparagaceae', 'Asparagus', 'CR — En peligro crítico (Lista Roja mundial de la UICN, 2018)', 'CEEA: En peligro de extinción (Orden TED/339/2023, de 30 de marzo)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', NULL, 33036, 8896846, NULL, NULL, NULL
    UNION ALL
    SELECT 'Gamoncillo', 'Asphodelus fistulosus', 'flora', 'Hierba', 'Pastizales secos, bordes de camino y terrenos removidos', 'LC', 'Gamón pequeño de hojas cilíndricas y huecas —de ahí su nombre— que salen todas de la base. Levanta un tallo ramificado con flores blancas de nervio rosado, que se abren de forma escalonada durante semanas. Es una de las primeras plantas en colonizar cunetas y baldíos.', NULL, 'Hojas finas, cilíndricas y huecas por dentro; Flores blancas con una raya rosa en cada pétalo; Cápsulas redondas y pequeñas al fructificar', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/A._fistulosus-flor-2.JPG?width=1280', 'Philmarin (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (3 hábitats; barrido de 2026-08-17); Decreto n.º 259/2019, de 10 de octubre, PRUG del Parque Regional «Salinas y Arenales de San Pedro del Pinatar» (volumen III del Plan de gestión integral del Mar Menor), §2.3.1.2 y §2.3.3.2 (BORM n.º 242, de 19 de octubre de 2019): la norma la enumera en el Parque Regional «Salinas y Arenales de San Pedro del Pinatar», que es el propio espacio: a diferencia de los planes del Altiplano, aquí el inventario NO es el de la ZEC sino el del parque, porque el volumen III es su PRUG; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Liliopsida', 'Asparagales', 'Asphodelaceae', 'Asphodelus', 'LC (Preocupación menor)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 2521, 2778437, NULL, NULL, NULL
