    SELECT 'Agua amarga', 'Ajuga iva', 'flora', 'Hierba', 'Vive en pastizales secos, en suelos calcáreos o arcillosos, como arvense o ruderal, hasta 1200 m', 'No catalogada', 'Hierba perenne, de 5-20 cm, leñosa abajo, con tallos tendidos peloso-lanosos. Hojas de 12-40 x 1,5-7 mm, espatuladas, enteras o algo dentadas, pubescentes. Inflorescencia espiciforme con flores en grupos de dos o tres, con brácteas foliosas sobresalientes. Cáliz de 3,5-7 mm, regular, pubescente, con dientes más cortos que el tubo. Corola de 13-24 mm, con labio superior muy corto y el inferior trilobulado, con lóbulo medio más largo y ancho, pubescente, en general de color rosado. Núculas de 2,5-3 mm, reticuladas, glabras, negruzcas.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ajuga_iva_Dingli_Cliffs_Malta_01_06_2010_01.jpg?width=1280', 'Denis Barthel (CC BY-SA 3.0 de) · Wikimedia Commons', NULL, NULL, 2, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 0 ocurrencias dentro de los polígonos de hábitat del espacio (0 hábitats; barrido de 2026-08-17); Decreto n.º 259/2019, de 10 de octubre, PRUG del Parque Regional «Salinas y Arenales de San Pedro del Pinatar» (volumen III del Plan de gestión integral del Mar Menor), §2.3.1.2 y §2.3.3.2 (BORM n.º 242, de 19 de octubre de 2019): la norma la enumera en el Parque Regional «Salinas y Arenales de San Pedro del Pinatar», que es el propio espacio: a diferencia de los planes del Altiplano, aquí el inventario NO es el de la ZEC sino el del parque, porque el volumen III es su PRUG; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Lamiaceae', 'Ajuga', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 1815, 7307171, NULL, NULL, NULL
    UNION ALL
    SELECT 'Ajestrín', 'Allium sphaerocephalon', 'flora', 'Planta bulbosa', 'Vive en praderas, lugares incultos y dunas, hasta 2350 m', 'No catalogada', 'Hierba perenne, con bulbo de 1-2,5 cm, ovoide o globoso, con algunos bulbillos, y con tallo de 20-70 cm, de sección circular, macizo; inflorescencia esférica, densa, de 1,3-5,3 cm de diámetro, con una espata de dos segmentos ovados, más cortos que las flores; estas con pedicelos hasta de 2,1 cm, con tépalos de 3,5-6 mm, de color rosado o púrpura; estambres seis, los internos con filamentos tricuspidados; cápsula de 3-4,5 mm.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Mayo a agosto', 'https://commons.wikimedia.org/wiki/Special:FilePath/Alcal%C3%A1_de_Henares_(RPS_01-06-2024)_Allium_sphaerocephalon.png?width=1280', 'Raimundo Pastor (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 0 ocurrencias dentro de los polígonos de hábitat del espacio (0 hábitats; barrido de 2026-08-17); Decreto n.º 259/2019, de 10 de octubre, PRUG del Parque Regional «Salinas y Arenales de San Pedro del Pinatar» (volumen III del Plan de gestión integral del Mar Menor), §2.3.1.2 y §2.3.3.2 (BORM n.º 242, de 19 de octubre de 2019): la norma la enumera en el Parque Regional «Salinas y Arenales de San Pedro del Pinatar», que es el propio espacio: a diferencia de los planes del Altiplano, aquí el inventario NO es el de la ZEC sino el del parque, porque el volumen III es su PRUG; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Liliopsida', 'Asparagales', 'Amaryllidaceae', 'Allium', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 2028, NULL, NULL, 