    SELECT 'Lagartija de Edwards', 'Psammodromus edwarsianus', 'fauna', 'Reptil', NULL, 'No catalogada', 'Se distingue de P. hispanicus y P. occidentalis por la presencia de una escama supralabial debajo de la escama subocular. Su cabeza es más puntiaguda, su coloración nupcial verde es mucho menos extendida, y tiene mayor número de poros femorales y escamas gulares que las dos especies hermanas. Tiene mayor número de ocelos, menor número de escamas ventrales y del collar, pesa menos y es más pequeño que P. hispanicus. Su boca es más picuda que la de P. hispanicus y menos picuda que la de P. occidentalis.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Febrero a noviembre', 'https://commons.wikimedia.org/wiki/Special:FilePath/Psammodromus_edwarsianus_521254282.jpg?width=1280', 'Donald Davesne (CC BY 4.0) · Wikimedia Commons', NULL, NULL, 3, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 0 ocurrencias dentro de los polígonos de hábitat del espacio (0 hábitats; barrido de 2026-08-17); Decreto n.º 259/2019, de 10 de octubre, PRUG del Parque Regional «Salinas y Arenales de San Pedro del Pinatar» (volumen III del Plan de gestión integral del Mar Menor), §2.3.1.2 y §2.3.3.2 (BORM n.º 242, de 19 de octubre de 2019): la norma la enumera en el Parque Regional «Salinas y Arenales de San Pedro del Pinatar», que es el propio espacio: a diferencia de los planes del Altiplano, aquí el inventario NO es el de la ZEC sino el del parque, porque el volumen III es su PRUG, que la cita como «Psammodromus edwardsianus» (errata de imprenta de la norma); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Chordata', 'Reptilia', 'Squamata', 'Lacertidae', 'Psammodromus', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 16216, 8323736, NULL, NULL, NULL
    UNION ALL
    SELECT 'Aramago', 'Rapistrum rugosum', 'flora', 'Hierba', 'Vive en bordes de camino y campos de cultivo, entre 10-1400 m', 'No catalogada', 'Hierba anual, de 15-150 cm, con tallo erecto, muy ramificado, con pelos tiesos abajo. Hojas basales de 3-25 x 1-11 cm, pecioladas, elípticas, de enteras a lirado-pinnatisectas, dentadas, las caulinares menores, sentadas y menos divididas. Flores en racimos largos, con numerosas flores con cuatro sépalos de 3-4 mm, glabros, verdosos, y cuatro pétalos de 6-9 mm, obovados amarillos. Seis estambres, dos más cortos. Fruto en silícula, con la parte inferior de 1-3 mm, hasta con tres semillas, y la parte superior de 2-4 mm, globosa, acanalada, con una semilla, y que acaba en un estilo de 1-2 mm, cónico. Semillas de 2 mm, lisas, color pardo.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Marzo a junio', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bolletjesraket_19-05-2006_12.34.12.JPG?width=1280', 'Me (Public domain) · Wikimedia Commons', NULL, NULL, 2, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 0 ocurrencias dentro de los polígonos de hábitat del espacio (0 hábitats; barrido de 2026-08-17); Decreto n.º 259/2019, de 10 de octubre, PRUG del Parque Regional «Salinas y Arenales de San Pedro del Pinatar» (volumen III del Plan de gestión integral del Mar Menor), §2.3.1.2 y §2.3.3.2 (BORM n.º 242, de 19 de octubre de 2019): la norma la enumera en el Parque Regional «Salinas y Arenales de San Pedro del Pinatar», que es el propio espacio: a diferencia de los planes del Altiplano, aquí el inventario NO es el de la ZEC sino el del parque, porque el volumen III es su PRUG, que la cita como «Rapistrum rugossum» (errata de imprenta de la norma); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Brassicales', 'Brassicaceae', 'Rapistrum', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 7583, 5373368, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cerraja gaditana', 'Reichardia gaditana', 'flora', 'Hierba', 'Arenas litorales, suelos salinos y eriales cercanos a la costa', 'No catalogada', 'Pariente cercana del cerrajón, anual y de hojas carnosas abrazadas al tallo, con capítulos amarillos y látex blanco. Es propia de suelos arenosos y algo salinos del suroeste y del sureste peninsular.', NULL, 'Hojas basales carnosas, con dientes anchos y triangulares; Capítulos amarillos con brácteas de borde membranoso; Látex blanco al partir cualquier parte de la planta', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Reichardia_gaditana_2.JPG?width=1280', 'Xemenendura (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 0 ocurrencias dentro de los polígonos de hábitat del espacio (0 hábitats; barrido de 2026-08-17); Decreto n.º 259/2019, de 10 de octubre, PRUG del Parque Regional «Salinas y Arenales de San Pedro del Pinatar» (volumen III del Plan de gestión integral del Mar Menor), §2.3.1.2 y §2.3.3.2 (BORM n.º 242, de 19 de octubre de 2019): la norma la enumera en el Parque Regional «Salinas y Arenales de San Pedro del Pinatar», que es el propio espacio: a diferencia de los planes del Altiplano, aquí el inventario NO es el de la ZEC sino el del parque, porque el volumen III es su PRUG; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Asterales', 'Asteraceae', 'Reichardia', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 638, 5385653, NULL, NULL, NULL
