    SELECT 'Abubilla', 'Upupa epops', 'fauna', 'Ave', 'Campos abiertos, dehesas, cultivos con arbolado y bordes de matorral', 'Protegida (LESRPE)', 'Ave inconfundible de color canela con alas y cola a franjas blancas y negras, y una cresta eréctil que despliega en abanico al posarse. Sondea el suelo blando con el pico largo y curvo en busca de larvas e insectos. Su canto, un «up-up-up» sordo y repetido, se oye de lejos en primavera.', NULL, 'Vuelo ondulante y torpe, como una mariposa grande; Cresta que abre en abanico justo al aterrizar; Camina por el suelo clavando el pico largo y curvo', 'Todo el año en el sur peninsular; estival en el resto', 'https://commons.wikimedia.org/wiki/Special:FilePath/Wiedehopf_mit_Puppe_als_Futter.jpg?width=1280', 'Sven Damerow (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 141 ocurrencias dentro del espacio (barrido de 2026-08-17); las aves no se adscriben a hábitats; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000175 (Salinas y Arenales de San Pedro del Pinatar), sección 3.2: población reproductora, presente; Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000175 (Salinas y Arenales de San Pedro del Pinatar), sección 3.2: población permanente, presente; Decreto n.º 259/2019, de 10 de octubre, PRUG del Parque Regional «Salinas y Arenales de San Pedro del Pinatar» (volumen III del Plan de gestión integral del Mar Menor), §2.3.1.2 y §2.3.3.2 (BORM n.º 242, de 19 de octubre de 2019): la norma la enumera en el Parque Regional «Salinas y Arenales de San Pedro del Pinatar», que es el propio espacio: a diferencia de los planes del Altiplano, aquí el inventario NO es el de la ZEC sino el del parque, porque el volumen III es su PRUG; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', NULL, NULL, 'Upupa', 'LC (Preocupación menor)', 'Directiva Aves 2009/147/CE (Red Natura 2000); LESRPE', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 11211, 2498415, 'ES0000175', 0, '{"tipos":["permanente","reproductora"],"etiqueta":"Residente todo el año · Reproductora: cría aquí","sitios":[{"code":"ES0000175","name":"Salinas y Arenales de San Pedro del Pinatar","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000175 (Salinas y Arenales de San Pedro del Pinatar), sección 3.2"}'
    UNION ALL
    SELECT 'Perdiz roja', 'Alectoris rufa', 'fauna', 'Ave', 'Mosaicos de cultivo, matorral bajo y laderas pedregosas', 'LC', 'Perdiz de patas y pico rojos, con un collar negro que se deshace en un salpicado de motas sobre el pecho y flancos barrados en blanco, negro y castaño. Prefiere correr a volar, y cuando por fin levanta lo hace de golpe y a ras de suelo, planeando ladera abajo.', NULL, 'Flancos con barras nítidas blancas, negras y castañas; Collar negro que se disgrega en motas sobre el pecho; Corre agachada antes que volar; levanta de golpe y planea', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Perdiz_roja.jpg?width=1280', 'Juan Lacruz (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Directiva Aves 2009/147/CE, Anexos II y III (especie cinegética)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"Directiva Aves 2009/147/CE, Anexos II y III (especie cinegética)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF confirma su presencia con 140 ocurrencias dentro del espacio (barrido de 2026-08-17); las aves no se adscriben a hábitats; Decreto n.º 259/2019, de 10 de octubre, PRUG del Parque Regional «Salinas y Arenales de San Pedro del Pinatar» (volumen III del Plan de gestión integral del Mar Menor), §2.3.1.2 y §2.3.3.2 (BORM n.º 242, de 19 de octubre de 2019): la norma la enumera en el Parque Regional «Salinas y Arenales de San Pedro del Pinatar», que es el propio espacio: a diferencia de los planes del Altiplano, aquí el inventario NO es el de la ZEC sino el del parque, porque el volumen III es su PRUG; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Chordata', 'Aves', 'Galliformes', 'Phasianidae', 'Alectoris', 'LC', 'No incluida en el LESRPE; Directiva Aves 2009/147/CE, Anexos II y III (especie cinegética)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 12114, 2474051, NULL, NULL, NULL
